mapper.select:
SELECT id, building_id AS siteId, code FROM `${unitTable}`

    building_id=#{siteId}

ORDER BY building_id, code

SELECT id, building_id AS siteId, code, capacity FROM `${unitTable}`

    building_id=#{siteId}

ORDER BY building_id, code

SELECT u.code AS code, s.name AS siteName
FROM `${unitTable}` u JOIN `${siteTable}` s ON s.id = u.building_id
WHERE u.id=#{unitId}
